// Which HTML files are site pages, and the public URL each one is served at.
//
// Shared by gen-sitemap.js (what to list) and subset-icons.js (what to scan for `ti ti-*`), so a new
// page directory only has to be added here. The URL mapping mirrors nginx.conf: blog pages are
// served without the .html extension and without a trailing slash, and the canonical tags that
// scripts/build-blog.js writes use the same spelling. /legal (legal.html, generated by
// scripts/build-legal.js) is served without the extension too.

const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', '..');
const SITE = 'https://vetcare.bg';

// '' is SRC itself. blog/ is generated by scripts/build-blog.js.
const PAGE_DIRS = ['', 'blog'];

// Paths relative to SRC, always with forward slashes ('index.html', 'blog/index.html', ...).
function htmlPages() {
  return PAGE_DIRS.flatMap((dir) => {
    let names;
    try {
      names = fs.readdirSync(path.join(SRC, dir));
    } catch (err) {
      if (err.code === 'ENOENT') return []; // blog/ before the first `npm run blog`
      throw err;
    }
    return names.filter((f) => f.endsWith('.html')).map((f) => (dir ? `${dir}/${f}` : f));
  });
}

function urlFor(file) {
  if (file === 'index.html') return `${SITE}/`;
  if (file === 'blog/index.html') return `${SITE}/blog`;
  if (file === 'legal.html') return `${SITE}/legal`;
  const post = file.match(/^blog\/([^/]+)\.html$/);
  if (post) return `${SITE}/blog/${post[1]}`;
  return `${SITE}/${file}`;
}

module.exports = { SRC, SITE, htmlPages, urlFor };
